// The original's small helpers serve the port too (human_movement*.cpp: later parts).
#ifndef HUMAN_MOVE
float AngleBetween2D(const float *a, const float *b)
{
    typedef float(__fastcall * T)(const float *, const float *);
    return OriginalAt<T>(0x00788a10)(a, b);
}
void RotateAboutY(S_vector &v, float angle)
{
    // (The original's takes a 16-byte vector: given a padded copy.)
    alignas(16) float pad[4] = {v.x, v.y, v.z, 0.0f};
    typedef void(__fastcall * T)(float *, int, float);
    OriginalAt<T>(0x007888f0)(pad, 0, angle);
    v = S_vector(pad[0], pad[1], pad[2]);
}
void RotateAboutX(S_vector4 &v, float angle)
{
    typedef void(__fastcall * T)(S_vector4 *, int, float);
    OriginalAt<T>(0x00788950)(&v, 0, angle);
}
#endif
