// The test human: a C_Human of raw memory (its constructor is not linked) with a vtable of loggers, its movement and
// work constructed (their in-class initializers), the equipment and its frame.
struct S_TestHuman {
    C_Human *human = nullptr;
    C_HumanMovement *movement = nullptr;
    C_HumanWork *work = nullptr;
    unsigned char *equipment = nullptr;
    unsigned char *pose = nullptr;                      // the weapon pose (the original's layout: shared)
    I3D_frame *frame = nullptr;
    I3D_frame *camera = nullptr;
    S_CollisionVolume stanceVolumes[4], hitVolumes[2];
};
// The original's copies.
alignas(16) uint8_t o_human[0x1000];
alignas(16) uint8_t o_movement[0xE00];
alignas(16) uint8_t o_work[0x100];
void *o_humanVt[96];
void *p_humanVt[128];
// The network game's settings (both sides read the same block) and the human's controller (its type at +0x48: 1 is
// the local player's, as the original's IsLocalPlayer reads it in a local game).
alignas(16) uint8_t g_mpBlock[0x400];
alignas(16) uint8_t g_controller[0x100];

// Virtual calls on the human (the port's slots by its own member pointers, the original's by its offsets).
void __attribute__((thiscall)) P_Hit(C_Human *self, E_HitType type, float amount, const S_vector &pos, const S_vector &dir, C_Actor *attacker,
                                     int flags)
{
    Log(self, "Hit", {double(type), amount, pos.x, pos.y, pos.z, dir.x, dir.y, dir.z, double(attacker != nullptr), double(flags)});
}
bool __attribute__((thiscall)) P_OnCollisionEx(C_Human *self, C_Actor *other, const S_vector *pos, int a3, int a4, int a5, int a6, int a7)
{
    const S_vector *move = reinterpret_cast<const S_vector *>(a3), *normal = reinterpret_cast<const S_vector *>(a4);
    Log(self, ("OnCollisionEx " + NameOf(other)).c_str(), {pos->x, pos->y, pos->z, move->x, move->y, move->z, normal->x, normal->y, normal->z,
                                                            double(a5), double(a6), double(a7)});
    return false;
}
void __attribute__((thiscall)) P_Unexpected(void *self)
{
    std::printf("unexpected virtual call on %s\n", NameOf(self).c_str());
    std::abort();
}
template <class F> size_t VSlot(F f)
{
    struct {
        uintptr_t ptr, adj;
    } m;
    std::memcpy(&m, &f, sizeof m);
    return (m.ptr - 1) / sizeof(void *);
}

S_TestHuman g_h;
const float *FramePos() { return &g_h.frame->GetMatrix().m[3][0]; }
void MakeHuman()
{
    S_TestHuman &h = g_h;
    const size_t size = sizeof(C_Human) + 0x100;
    auto *bytes = static_cast<unsigned char *>(::operator new(size, std::align_val_t(16)));
    std::memset(bytes, 0, size);
    h.human = reinterpret_cast<C_Human *>(bytes);
    for (void *&slot : p_humanVt)
        slot = reinterpret_cast<void *>(P_Unexpected);
    p_humanVt[VSlot(&C_Actor::Hit)] = reinterpret_cast<void *>(P_Hit);
    p_humanVt[VSlot(&C_Actor::OnCollisionEx)] = reinterpret_cast<void *>(P_OnCollisionEx);
    *reinterpret_cast<void ***>(h.human) = p_humanVt;
    h.human->m_type = ACTOR_HUMAN;
    h.human->m_netId = 7;
    h.human->m_role = HUMAN_ROLE_PLAYER;
    for (int i = 0; i < STAT_COUNT; ++i)
        h.human->m_stats[i] = 80;
    h.movement = new (::operator new(sizeof(C_HumanMovement), std::align_val_t(16))) C_HumanMovement();
    h.work = new C_HumanWork();
    h.equipment = new unsigned char[0x400]();
    h.pose = static_cast<unsigned char *>(::operator new(sizeof(C_HumanWeaponPose) + 0x100, std::align_val_t(16)));
    std::memset(h.pose, 0, sizeof(C_HumanWeaponPose) + 0x100);
    h.frame = NewFrame(FRAME_MODEL, "human", S_vector(20, 1, 20), Identity(), Box(S_vector(0.3f, 0.9f, 0.3f)), "", g_sector);
    h.human->m_frame = h.frame;
    h.human->m_controller = reinterpret_cast<C_HumanController *>(g_controller);
    GetGame()->m_scene = reinterpret_cast<I3D_scene *>(g_sceneBytes);
    g_names[g_sceneBytes] = "scene";
    g_mpSettings = reinterpret_cast<S_MultiplayerSettings *>(g_mpBlock);
    h.human->m_body.owner = h.human;
    h.human->m_body.movement = h.movement;
    h.human->m_body.work = h.work;
    h.human->m_body.equipment = reinterpret_cast<C_HumanEquipment *>(h.equipment);
    h.movement->m_owner = h.human;
    h.movement->m_weaponPose = h.movement->m_weaponPose2 = reinterpret_cast<C_HumanWeaponPose *>(h.pose);
    // The active camera of the scene (+0x15C; its fields read inline: FOV +0x120, range +0x124 / +0x128, aspect +0x138).
    h.camera = NewFrame(FRAME_DUMMY, "camera", S_vector(32, 3, 2), Identity(), Box(S_vector(0.1f, 0.1f, 0.1f)), "", g_sector);
    *reinterpret_cast<I3D_frame **>(g_sceneBytes + 0x15C) = h.camera;
    h.work->m_movement = h.movement;
    h.work->m_movementBase = h.movement;
    h.work->m_owner = &h.movement->m_owner;
    C_HumanMovement *m = h.movement;
    m->m_locomotion.m_owner = h.human;
    m->m_locomotion.m_movement = m;
    m->m_locomotion.m_specialMoves = &m->m_specialMoves;
    m->m_locomotion.m_animPlayer = &m->m_animPlayer;
    for (int i = 0; i < 4; ++i)
        m->m_stanceVolumes[i] = &h.stanceVolumes[i];
    for (int i = 0; i < 2; ++i)
        m->m_hitVolumes[i] = &h.hitVolumes[i];

    // The names (the port's objects and the original's copies alike).
    g_names[h.human] = g_names[o_human] = "human";
    g_names[m] = g_names[o_movement] = "movement";
    g_names[h.work] = g_names[o_work] = "work";
    g_names[h.equipment] = "equipment";
    g_names[h.pose] = "weaponPose";
    g_portHuman = h.human;
    NameTeam();
    g_names[&m->m_mixer] = g_names[o_movement + 0x260] = "mixer";
    g_names[&m->m_morph] = g_names[o_movement + 0x610] = "morph";
    g_names[&m->m_specialMoves] = g_names[o_movement + 0xAA0] = "specialMoves";
    g_names[&m->m_locomotion] = g_names[o_movement + 0xAC0] = "locomotion";
    g_names[&m->m_animPlayer] = g_names[o_movement + 0xC00] = "animPlayer";
    g_names[&m->m_visual] = g_names[o_movement + 0xCD0] = "visual";
    g_names[h.frame] = "frame";
}

// The port's g_assumedGround (human_locomotion.cpp, in its anonymous namespace): the volume a move returned that is
// in this image and not one of the test's (found by NoteAssumedGround); the original's is at 0x00983350.
const void *g_portAssumedGround = nullptr;
// Port object -> its copy (the pointers in the copies are rewritten by this table).
// More objects with a copy of their own (the actors of the contacts test).
std::vector<std::pair<const void *, void *>> g_extraPointers;
std::vector<std::pair<const void *, void *>> PointerMap()
{
    C_HumanMovement *m = g_h.movement;
    std::vector<std::pair<const void *, void *>> map = {{g_h.human, o_human},
            {m, o_movement},
            {g_h.work, o_work},
            {&m->m_mixer, o_movement + 0x260},
            {&m->m_morph, o_movement + 0x610},
            {&m->m_specialMoves, o_movement + 0xAA0},
            {&m->m_locomotion, o_movement + 0xAC0},
            {&m->m_animPlayer, o_movement + 0xC00},
            {&m->m_idle, o_movement + 0xCB0},
            {&m->m_visual, o_movement + 0xCD0},
            {&m->m_owner, o_movement + 0x258},
            {g_portAssumedGround, OriginalAt<void *>(0x00983350)}};
    map.insert(map.end(), g_extraPointers.begin(), g_extraPointers.end());
    return map;
}
void Remap(uint8_t *bytes, size_t size, const std::vector<std::pair<const void *, void *>> &map)
{
    for (size_t i = 0; i + 4 <= size; i += 4) {
        uint32_t w;
        std::memcpy(&w, bytes + i, 4);
        for (const auto &pq : map)
            if (pq.first && w == static_cast<uint32_t>(reinterpret_cast<uintptr_t>(pq.first))) {
                const uint32_t to = static_cast<uint32_t>(reinterpret_cast<uintptr_t>(pq.second));
                std::memcpy(bytes + i, &to, 4);
                break;
            }
    }
}
// The original's globals the locomotion reads and writes.
const uint32_t O_GAME_ROLE = 0x00982100;
const uint32_t O_MOVE_ITERATIONS = 0x008441e4;
const uint32_t O_MP_SETTINGS = 0x008aea30;               // -> the settings (fallingDamage at +0x258)
const uint32_t O_LOCAL_PLAYER_SLOT = 0x00982104;
const uint32_t O_CAMERA_UNDER_WATER = 0x0098a6ac;     // g_cameraUnderWater (read inline)

// More of the port's state in the original's layout (the containers: base3_test.inc).
void (*g_toOriginalExtra)();
// The state of the port's objects in the original's layout (into o_*).
void ToOriginal()
{
    std::memset(o_human, 0, sizeof o_human);
    std::memset(o_movement, 0, sizeof o_movement);
    std::memset(o_work, 0, sizeof o_work);
    const auto *ph = reinterpret_cast<const uint8_t *>(g_h.human);
    for (const S_LayoutField &f : kActorFields)
        std::memcpy(o_human + f.orig, ph + f.port, f.size);
    for (const S_LayoutField &f : kHumanFields)
        std::memcpy(o_human + f.orig, ph + f.port, f.size);
    *reinterpret_cast<void ***>(o_human) = o_humanVt;
    const auto *pm = reinterpret_cast<const uint8_t *>(g_h.movement);
    for (const S_LayoutField &f : kMovementFields)
        std::memcpy(o_movement + f.orig, pm + f.port, f.size);
    std::memcpy(o_work, static_cast<const void *>(g_h.work), sizeof(C_HumanWork));
    const auto map = PointerMap();
    Remap(o_human, sizeof o_human, map);
    Remap(o_movement, sizeof o_movement, map);
    Remap(o_work, sizeof o_work, map);
    *OriginalAt<uint32_t *>(O_GAME_ROLE) = g_gameRole;
    *OriginalAt<void **>(O_MP_SETTINGS) = g_mpBlock;
    *OriginalAt<int *>(O_LOCAL_PLAYER_SLOT) = g_script.localPlayer ? g_h.human->m_netId : 99;
    g_controller[0x48] = g_script.localPlayer ? 1 : 0;
    *OriginalAt<float *>(O_MOVE_ITERATIONS) = g_moveIterations;
    *OriginalAt<bool *>(O_CAMERA_UNDER_WATER) = g_script.cameraUnderWater;
    if (g_toOriginalExtra)
        g_toOriginalExtra();
}

// ---- comparing the copies: by field, floats within a tolerance
float g_tol = 2e-4f;
bool FloatLike(uint32_t w)
{
    const uint32_t e = (w >> 23) & 0xFF;
    return w == 0 || w == 0x80000000u || (e >= 127 - 40 && e <= 127 + 40);
}
bool WordsNear(uint32_t a, uint32_t b, char kind)
{
    if (a == b)
        return true;
    if (kind == 'p' || kind == 'i')
        return false;
    if (kind == 'm' && !(FloatLike(a) && FloatLike(b)))
        return false;
    float x, y;
    std::memcpy(&x, &a, 4);
    std::memcpy(&y, &b, 4);
    return std::fabs(x - y) <= g_tol * std::max(1.0f, std::fabs(x));
}
// Fields not compared (by name), and words of a field not compared for now (name, byte offset).
std::set<std::string> g_skipFields;
std::set<std::pair<std::string, size_t>> g_skipWords;
// The first field that differs (name and word) between two copies of an object by its table, or "".
template <size_t N> std::string FieldsDiffer(const S_LayoutField (&fields)[N], const uint8_t *a, const uint8_t *b, const char *object)
{
    for (const S_LayoutField &f : fields) {
        if (g_skipFields.count(f.name))
            continue;
        // (The w of the human's position, direction and velocity, and of the movement's blood pool place and normal:
        // the original often writes an undefined one there; the port keeps the owner's, as human_locomotion.cpp says.)
        const bool anyW = std::strcmp(f.name, "m_position") == 0 || std::strcmp(f.name, "m_direction") == 0 ||
                          std::strcmp(f.name, "m_velocity") == 0 || std::strcmp(f.name, "m_unknown9F0") == 0 ||
                          std::strcmp(f.name, "m_unknownA00") == 0 || std::strcmp(f.name, "m_dummyPos") == 0 || std::strcmp(f.name, "m_dummyOffset") == 0 ||
                          std::strcmp(f.name, "m_hitOffsets") == 0 ||   // (UpdateHitSpheres: from a stack temp's w)
                          std::strcmp(f.name, "m_unknown240") == 0 ||   // (ResetBase: likewise)
                          std::strcmp(f.name, "m_unknown9D0") == 0 ||   // (LoadBase: 12 bytes read, 16 copied)
                          std::strcmp(f.name, "m_unknown940") == 0;     // (likewise)
        const bool locomotion = std::strcmp(f.name, "m_locomotion") == 0;
        // (The mixer's vectors' w, +0x230..+0x320: Init, Update and LoadGame store stack temps' undefined ones.)
        const bool mixer = std::strcmp(f.name, "m_mixer") == 0;
        const bool request = std::strcmp(f.name, "m_request") == 0;
        for (size_t i = 0; i < f.size; i += 4) {
            if (anyW && i % 16 == 12)
                continue;
            // (The command record's unknown10.w and facingDir.w: S_MoveRequest::Reset copies undefined ones in.)
            if (request && (i == 0x1C || i == 0x2C))
                continue;
            // (The locomotion's vectors' w: m_unknown000, m_move, m_turnTarget, m_unknown030, m_push, m_volumesDir,
            // m_velocity, m_unknown0C0; the original copies undefined ones in.)
            if (locomotion && i < 0xD0 && i % 16 == 12 && i != 0x4C && i != 0x5C && i != 0x6C && i != 0x8C && i != 0x9C)
                continue;
            if (mixer && i >= 0x230 && i < 0x320 && i % 16 == 12)
                continue;
            if (!g_skipWords.empty() && g_skipWords.count({f.name, i}))
                continue;
            uint32_t x = 0, y = 0;
            const size_t n = std::min<size_t>(4, f.size - i);
            std::memcpy(&x, a + f.orig + i, n);
            std::memcpy(&y, b + f.orig + i, n);
            if (!WordsNear(x, y, f.kind)) {
                char text[160];
                std::snprintf(text, sizeof text, "%s.%s+%u (port %08x original %08x)", object, f.name, static_cast<unsigned>(i), x, y);
                return text;
            }
        }
    }
    return "";
}
bool CallsAgree(const std::vector<S_Call> &a, const std::vector<S_Call> &b, std::string &why)
{
    for (size_t i = 0; i < std::max(a.size(), b.size()); ++i) {
        if (i >= a.size() || i >= b.size() || a[i].what != b[i].what || a[i].nums.size() != b[i].nums.size()) {
            why = "call " + std::to_string(i) + ": port " + (i < a.size() ? a[i].what : "-") + ", original " + (i < b.size() ? b[i].what : "-");
            return false;
        }
        for (size_t k = 0; k < a[i].nums.size(); ++k) {
            // (Whole numbers on both sides, counts and times, are compared exactly: the float tolerance passed 10000
            // against 10001.)
            const double x = a[i].nums[k], y = b[i].nums[k];
            const bool whole = x == std::floor(x) && y == std::floor(y) && std::fabs(x) < 16777216.0 && std::fabs(y) < 16777216.0;
            if ((whole && x != y) || std::fabs(x - y) > g_tol * std::max(1.0, std::fabs(x))) {
                why = "call " + std::to_string(i) + " " + a[i].what + " argument " + std::to_string(k) + ": port " + std::to_string(a[i].nums[k]) +
                      ", original " + std::to_string(b[i].nums[k]);
                return false;
            }
        }
    }
    return true;
}
